def handle(app, svc):
    resp = svc.apply(app)
    outcome = resp["result"]["outcome"]
    credit_limit = resp["result"]["credit_limit"]

    # Network referral rule (spec section 4):
    # self_employed applicant with requested_limit above 6000 must go to manual
    # review instead of being issued. A decline stays a decline.
    if (app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000
            and outcome == "approved"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review (replaces v1 "refer"): queue for review, do NOT decline
    return {"action": "queue_review", "limit": 0}
